/* eslint-disable max-params */

'use strict';

// MODULES //

var arraylike2object = require( '@stdlib/array/base/arraylike2object' );
var accessors = require( './accessors.js' );


// MAIN //

/**
* Generates a Cauchy matrix using alternative indexing semantics.
*
* @param {NonNegativeInteger} M - number of indexed elements in `x`
* @param {NonNegativeInteger} N - number of indexed elements in `y`
* @param {Collection} x - first input array
* @param {integer} strideX - stride length for `x`
* @param {NonNegativeInteger} offsetX - starting index for `x`
* @param {Collection} y - second input array
* @param {integer} strideY - stride length for `y`
* @param {NonNegativeInteger} offsetY - starting index for `y`
* @param {Collection} out - output array
* @param {integer} strideOut1 - stride length for the first dimension of `out`
* @param {integer} strideOut2 - stride length for the second dimension of `out`
* @param {NonNegativeInteger} offsetOut - starting index for `out`
* @returns {Collection} output array
*
* @example
* var x = [ 3.0, 5.0 ];
* var y = [ 1.0, 4.0 ];
* var out = [ 0.0, 0.0, 0.0, 0.0 ];
*
* gcauchyMatrix( x.length, y.length, x, 1, 0, y, 1, 0, out, 2, 1, 0 );
* // out => [ 0.5, -1.0, 0.25, 1.0 ]
*/
function gcauchyMatrix( M, N, x, strideX, offsetX, y, strideY, offsetY, out, strideOut1, strideOut2, offsetOut ) { // eslint-disable-line max-len
	var ox;
	var oy;
	var oo;
	var ix;
	var iy;
	var io;
	var ij;
	var v;
	var i;
	var j;

	if ( M <= 0 || N <= 0 ) {
		return out;
	}
	ox = arraylike2object( x );
	oy = arraylike2object( y );
	oo = arraylike2object( out );
	if ( ox.accessorProtocol || oy.accessorProtocol || oo.accessorProtocol ) {
		accessors( M, N, ox, strideX, offsetX, oy, strideY, offsetY, oo, strideOut1, strideOut2, offsetOut ); // eslint-disable-line max-len
		return out;
	}
	ix = offsetX;
	io = offsetOut;
	for ( i = 0; i < M; i++ ) {
		v = x[ ix ];
		iy = offsetY;
		ij = io;
		for ( j = 0; j < N; j++ ) {
			out[ ij ] = 1.0 / ( v - y[ iy ] );
			iy += strideY;
			ij += strideOut2;
		}
		ix += strideX;
		io += strideOut1;
	}
	return out;
}


// EXPORTS //

module.exports = gcauchyMatrix;
